  imported: 'Đã nhập {n} việc.',
  confirmReplace: 'Thay {n} việc hiện có bằng {m} việc trong file?',
  confirmReplaceUnreadable: 'Thay danh sách đã lưu không đọc được bằng {m} việc trong file?',
